/*
cluster.go — Tarjan's Strongly Connected Components algorithm.

Implements: cluster_functions tool from tool-schemas.json

Input:  AST graph JSON (from py-ast-core:extract_repo_ast)
Output: Three cluster arrays:
  - cluster_a: Independent leaf symbol IDs (zero outbound internal deps)
  - cluster_b: Interdependent symbol groups with coupling scores
  - cluster_c: Delicate/dynamic nodes with detected patterns and risk scores

Algorithm:
 1. Parse AST graph JSON into adjacency list.
 2. Pre-tag Cluster C from dynamic_flags_json (if provided).
 3. Run Tarjan's SCC on all non-Cluster-C nodes.
 4. Classify:
    - SCC of size 1 with no outbound internal edges → Cluster A
    - SCC of size > 1 (or nodes in coupled groups) → Cluster B
      (split into sub-clusters when size > max_cluster_size)
*/
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// ── Request / Response Types ────────────────────────────────────────────────

type ClusterFunctionsRequest struct {
	ASTGraphJSON     string `json:"ast_graph_json"`
	MaxClusterSize   int    `json:"max_cluster_size,omitempty"`
	DynamicFlagsJSON string `json:"dynamic_flags_json,omitempty"`
}

type ClusterBEntry struct {
	ClusterID     string   `json:"cluster_id"`
	Symbols       []string `json:"symbols"`
	CouplingScore float64  `json:"coupling_score"`
}

type ClusterCEntry struct {
	SymbolID        string   `json:"symbol_id"`
	DynamicPatterns []string `json:"dynamic_patterns"`
	RiskScore       float64  `json:"risk_score"`
}

type ClusterFunctionsResponse struct {
	ClusterA []string        `json:"cluster_a"`
	ClusterB []ClusterBEntry `json:"cluster_b"`
	ClusterC []ClusterCEntry `json:"cluster_c"`
}

// ── AST Graph JSON shape ─────────────────────────────────────────────────────
// Accepts either:
//   {"symbols": [...], "edges": [...]}
// or a flat edge-list:
//   [{"from":"A","to":"B"}, ...]

type astGraphEnvelope struct {
	Symbols []astSymbol `json:"symbols"`
	Edges   []astEdge   `json:"edges"`
}

type astSymbol struct {
	ID   string `json:"id"`
	Name string `json:"name,omitempty"`
}

type astEdge struct {
	From string `json:"from"`
	To   string `json:"to"`
}

// ── Dynamic Flags JSON shape ─────────────────────────────────────────────────
// [{"symbol_id":"X","patterns":["reflection","eval"],"risk_score":0.9}, ...]

type dynamicFlag struct {
	SymbolID string   `json:"symbol_id"`
	Patterns []string `json:"patterns"`
	RiskScore float64 `json:"risk_score"`
}

// ── Tarjan's SCC ─────────────────────────────────────────────────────────────

type tarjanState struct {
	adj     map[string][]string
	index   map[string]int
	lowlink map[string]int
	onStack map[string]bool
	stack   []string
	counter int
	sccs    [][]string
}

func tarjanSCC(nodes []string, adj map[string][]string) [][]string {
	ts := &tarjanState{
		adj:     adj,
		index:   make(map[string]int),
		lowlink: make(map[string]int),
		onStack: make(map[string]bool),
	}
	for _, n := range nodes {
		if _, visited := ts.index[n]; !visited {
			ts.strongconnect(n)
		}
	}
	return ts.sccs
}

func (ts *tarjanState) strongconnect(v string) {
	ts.index[v] = ts.counter
	ts.lowlink[v] = ts.counter
	ts.counter++
	ts.stack = append(ts.stack, v)
	ts.onStack[v] = true

	for _, w := range ts.adj[v] {
		if _, visited := ts.index[w]; !visited {
			ts.strongconnect(w)
			if ts.lowlink[w] < ts.lowlink[v] {
				ts.lowlink[v] = ts.lowlink[w]
			}
		} else if ts.onStack[w] {
			if ts.index[w] < ts.lowlink[v] {
				ts.lowlink[v] = ts.index[w]
			}
		}
	}

	if ts.lowlink[v] == ts.index[v] {
		var scc []string
		for {
			w := ts.stack[len(ts.stack)-1]
			ts.stack = ts.stack[:len(ts.stack)-1]
			ts.onStack[w] = false
			scc = append(scc, w)
			if w == v {
				break
			}
		}
		ts.sccs = append(ts.sccs, scc)
	}
}

// ── Handler ─────────────────────────────────────────────────────────────────

func clusterFunctionsHandler(w http.ResponseWriter, r *http.Request) {
	var req ClusterFunctionsRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		jsonError(w, err.Error(), http.StatusBadRequest)
		return
	}
	if req.MaxClusterSize == 0 {
		req.MaxClusterSize = 8
	}

	// 1. Parse AST graph JSON ------------------------------------------------
	var envelope astGraphEnvelope
	if err := json.Unmarshal([]byte(req.ASTGraphJSON), &envelope); err != nil {
		jsonError(w, fmt.Sprintf("invalid ast_graph_json: %s", err.Error()), http.StatusBadRequest)
		return
	}

	// Build node set and adjacency list from whichever shape was provided.
	nodeSet := make(map[string]struct{})
	adj := make(map[string][]string)

	for _, sym := range envelope.Symbols {
		nodeSet[sym.ID] = struct{}{}
	}
	for _, e := range envelope.Edges {
		nodeSet[e.From] = struct{}{}
		nodeSet[e.To] = struct{}{}
		adj[e.From] = append(adj[e.From], e.To)
	}

	// 2. Parse dynamic_flags_json → pre-tag Cluster C ------------------------
	clusterCMap := make(map[string]ClusterCEntry) // symbol_id → entry
	if req.DynamicFlagsJSON != "" {
		var flags []dynamicFlag
		if err := json.Unmarshal([]byte(req.DynamicFlagsJSON), &flags); err != nil {
			jsonError(w, fmt.Sprintf("invalid dynamic_flags_json: %s", err.Error()), http.StatusBadRequest)
			return
		}
		for _, f := range flags {
			patterns := f.Patterns
			if len(patterns) == 0 {
				patterns = []string{}
			}
			clusterCMap[f.SymbolID] = ClusterCEntry{
				SymbolID:        f.SymbolID,
				DynamicPatterns: patterns,
				RiskScore:       f.RiskScore,
			}
			// Ensure node exists even if not in symbol list
			nodeSet[f.SymbolID] = struct{}{}
		}
	}

	// 3. Collect non-Cluster-C nodes -----------------------------------------
	var nonCNodes []string
	for id := range nodeSet {
		if _, isC := clusterCMap[id]; !isC {
			nonCNodes = append(nonCNodes, id)
		}
	}

	// Build restricted adjacency list (only non-C nodes)
	nonCSet := make(map[string]struct{}, len(nonCNodes))
	for _, n := range nonCNodes {
		nonCSet[n] = struct{}{}
	}
	adjNonC := make(map[string][]string, len(nonCNodes))
	for _, n := range nonCNodes {
		for _, to := range adj[n] {
			if _, ok := nonCSet[to]; ok {
				adjNonC[n] = append(adjNonC[n], to)
			}
		}
	}

	// 4. Run Tarjan's SCC on non-C nodes -------------------------------------
	sccs := tarjanSCC(nonCNodes, adjNonC)

	// 5. Count internal edges per SCC ----------------------------------------
	// For coupling_score we count directed edges whose both endpoints are in the SCC.
	inSCC := make(map[string]int) // node → SCC index
	for i, scc := range sccs {
		for _, n := range scc {
			inSCC[n] = i
		}
	}

	internalEdgeCount := make([]int, len(sccs))
	for _, n := range nonCNodes {
		si := inSCC[n]
		for _, to := range adjNonC[n] {
			if inSCC[to] == si {
				internalEdgeCount[si]++
			}
		}
	}

	// 6. Classify SCCs into Cluster A / B ------------------------------------
	var clusterA []string
	var clusterB []ClusterBEntry
	bSeq := 0

	for i, scc := range sccs {
		if len(scc) == 1 && internalEdgeCount[i] == 0 {
			// Leaf: no outbound edges within the internal graph
			hasOut := false
			for _, to := range adjNonC[scc[0]] {
				if _, ok := nonCSet[to]; ok {
					hasOut = true
					break
				}
			}
			if !hasOut {
				clusterA = append(clusterA, scc[0])
				continue
			}
		}

		// Cluster B — may need splitting if size > max_cluster_size
		chunks := splitChunks(scc, req.MaxClusterSize)
		for _, chunk := range chunks {
			// Count edges internal to this chunk
			chunkSet := make(map[string]struct{}, len(chunk))
			for _, n := range chunk {
				chunkSet[n] = struct{}{}
			}
			edges := 0
			for _, n := range chunk {
				for _, to := range adjNonC[n] {
					if _, ok := chunkSet[to]; ok {
						edges++
					}
				}
			}
			score := 0.0
			if len(chunk) > 0 {
				score = float64(edges) / float64(len(chunk))
			}
			bSeq++
			clusterB = append(clusterB, ClusterBEntry{
				ClusterID:     fmt.Sprintf("B%d", bSeq),
				Symbols:       chunk,
				CouplingScore: score,
			})
		}
	}

	// 7. Build final Cluster C slice -----------------------------------------
	var clusterC []ClusterCEntry
	for _, entry := range clusterCMap {
		clusterC = append(clusterC, entry)
	}

	// Ensure non-nil slices in JSON output
	if clusterA == nil {
		clusterA = []string{}
	}
	if clusterB == nil {
		clusterB = []ClusterBEntry{}
	}
	if clusterC == nil {
		clusterC = []ClusterCEntry{}
	}

	resp := ClusterFunctionsResponse{
		ClusterA: clusterA,
		ClusterB: clusterB,
		ClusterC: clusterC,
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// splitChunks divides slice into sub-slices of at most size n.
func splitChunks(s []string, n int) [][]string {
	if n <= 0 || len(s) <= n {
		return [][]string{s}
	}
	var chunks [][]string
	for len(s) > 0 {
		end := n
		if end > len(s) {
			end = len(s)
		}
		chunks = append(chunks, s[:end])
		s = s[end:]
	}
	return chunks
}

// jsonError writes a JSON error body with the given status code.
func jsonError(w http.ResponseWriter, msg string, code int) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	fmt.Fprintf(w, `{"error":%s}`, jsonString(msg))
}

// jsonString returns a JSON-encoded string literal.
func jsonString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

