func clusterFunctionsHandler(w http.ResponseWriter, r *http.Request) {
	var req ClusterFunctionsRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		jsonError(w, err.Error(), http.StatusBadRequest)
