	nodeSet := make(map[string]struct{})
	adj := make(map[string][]string)

	for _, sym := range envelope.Symbols {
		nodeSet[sym.ID] = struct{}{}
	}
	for _, e := range envelope.Edges {
		nodeSet[e.From] = struct{}{}
		nodeSet[e.To] = struct{}{}
		adj[e.From] = append(adj[e.From], e.To)
	}

	// 2. Parse dynamic_flags_json → pre-tag Cluster C ------------------------
	clusterCMap := make(map[string]ClusterCEntry) // symbol_id → entry
	if req.DynamicFlagsJSON != "" {
		var flags []dynamicFlag
		if err := json.Unmarshal([]byte(req.DynamicFlagsJSON), &flags); err != nil {
			jsonError(w, fmt.Sprintf("invalid dynamic_flags_json: %s", err.Error()), http.StatusBadRequest)
			return
		}
		for _, f := range flags {
			patterns := f.Patterns
			if len(patterns) == 0 {
				patterns = []string{}
			}
			clusterCMap[f.SymbolID] = ClusterCEntry{
				SymbolID:        f.SymbolID,
				DynamicPatterns: patterns,
				RiskScore:       f.RiskScore,
			}
			// Ensure node exists even if not in symbol list
			nodeSet[f.SymbolID] = struct{}{}
		}
	}

	// 3. Collect non-Cluster-C nodes -----------------------------------------
	var nonCNodes []string
	for id := range nodeSet {
		if _, isC := clusterCMap[id]; !isC {
			nonCNodes = append(nonCNodes, id)
		}
	}

	// Build restricted adjacency list (only non-C nodes)
	nonCSet := make(map[string]struct{}, len(nonCNodes))
	for _, n := range nonCNodes {
		nonCSet[n] = struct{}{}
	}
	adjNonC := make(map[string][]string, len(nonCNodes))
	for _, n := range nonCNodes {
		for _, to := range adj[n] {
			if _, ok := nonCSet[to]; ok {
				adjNonC[n] = append(adjNonC[n], to)
			}
		}
	}

