		chunks := splitChunks(scc, req.MaxClusterSize)
		for _, chunk := range chunks {
			// Count edges internal to this chunk
			chunkSet := make(map[string]struct{}, len(chunk))
			for _, n := range chunk {
				chunkSet[n] = struct{}{}
			}
			edges := 0
			for _, n := range chunk {
				for _, to := range adjNonC[n] {
					if _, ok := chunkSet[to]; ok {
						edges++
					}
				}
			}
			score := 0.0
			if len(chunk) > 0 {
				score = float64(edges) / float64(len(chunk))
			}
			bSeq++
			clusterB = append(clusterB, ClusterBEntry{
				ClusterID:     fmt.Sprintf("B%d", bSeq),
				Symbols:       chunk,
				CouplingScore: score,
			})
		}
	}

	// 7. Build final Cluster C slice -----------------------------------------
	var clusterC []ClusterCEntry
	for _, entry := range clusterCMap {
		clusterC = append(clusterC, entry)
	}

	// Ensure non-nil slices in JSON output
	if clusterA == nil {
		clusterA = []string{}
	}
	if clusterB == nil {
		clusterB = []ClusterBEntry{}
	}
	if clusterC == nil {
		clusterC = []ClusterCEntry{}
	}

	resp := ClusterFunctionsResponse{
		ClusterA: clusterA,
		ClusterB: clusterB,
		ClusterC: clusterC,
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// splitChunks divides slice into sub-slices of at most size n.
func splitChunks(s []string, n int) [][]string {
	if n <= 0 || len(s) <= n {
		return [][]string{s}
	}
	var chunks [][]string
	for len(s) > 0 {
		end := n
		if end > len(s) {
			end = len(s)
		}
		chunks = append(chunks, s[:end])
		s = s[end:]
	}
	return chunks
}

// jsonError writes a JSON error body with the given status code.
func jsonError(w http.ResponseWriter, msg string, code int) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	fmt.Fprintf(w, `{"error":%s}`, jsonString(msg))
}

// jsonString returns a JSON-encoded string literal.
func jsonString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

