/*
worktree.go — Git worktree lifecycle management.

Implements: manage_worktree tool from tool-schemas.json

Actions:
  - create:  Create an isolated git worktree for a subagent cluster
  - merge:   Merge verified worktree back into target branch
  - cleanup: Remove spent worktree after successful merge
  - status:  Check worktree existence and branch state

Directory layout:
  project-root/
  ├── src/                           ← Main working tree (untouched)
  └── ../worktrees/
      ├── agent-cluster-auth/        ← Subagent A's workspace
      ├── agent-cluster-api/         ← Subagent B's workspace
      └── agent-cluster-events/      ← Subagent C's workspace
*/
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"os/exec"
	"path/filepath"
	"strings"
)

// ── Request / Response Types ────────────────────────────────────────────────

type ManageWorktreeRequest struct {
	Action        string `json:"action"`
	BranchName    string `json:"branch_name"`
	WorktreePath  string `json:"worktree_path,omitempty"`
	MergeStrategy string `json:"merge_strategy,omitempty"`
}

type ManageWorktreeResponse struct {
	Success        bool     `json:"success"`
	WorktreePath   string   `json:"worktree_path"`
	BranchName     string   `json:"branch_name"`
	MergeConflicts []string `json:"merge_conflicts,omitempty"`
}

// ── Handler ─────────────────────────────────────────────────────────────────

func manageWorktreeHandler(w http.ResponseWriter, r *http.Request) {
	var req ManageWorktreeRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		jsonError(w, err.Error(), http.StatusBadRequest)
		return
	}
	if req.Action == "" || req.BranchName == "" {
		jsonError(w, "action and branch_name are required", http.StatusBadRequest)
		return
	}
	if req.MergeStrategy == "" {
		req.MergeStrategy = "recursive"
	}
	if req.WorktreePath == "" {
		req.WorktreePath = filepath.Join("..", "worktrees", req.BranchName)
	}

	var resp ManageWorktreeResponse
	resp.BranchName = req.BranchName
	resp.WorktreePath = req.WorktreePath

	var err error
	switch req.Action {
	case "create":
		err = worktreeCreate(req.BranchName, req.WorktreePath)
	case "merge":
		var conflicts []string
		conflicts, err = worktreeMerge(req.BranchName, req.MergeStrategy)
		resp.MergeConflicts = conflicts
	case "cleanup":
		err = worktreeCleanup(req.WorktreePath)
	case "status":
		err = worktreeStatus(&resp)
	default:
		jsonError(w, fmt.Sprintf("unknown action %q; must be create|merge|cleanup|status", req.Action), http.StatusBadRequest)
		return
	}

	if err != nil {
		jsonError(w, err.Error(), http.StatusInternalServerError)
		return
	}

	resp.Success = true
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// ── Action implementations ───────────────────────────────────────────────────

// worktreeCreate runs `git worktree add [-b <branch>] <path> [<branch>]`.
// It first checks whether the branch already exists to decide whether -b is needed.
func worktreeCreate(branch, path string) error {
	// Check if branch exists
	checkCmd := exec.Command("git", "rev-parse", "--verify", branch)
	if err := checkCmd.Run(); err != nil {
